/* From Uiverse.io by mrhyddenn - Tags: loader */
.__UIV_SCOPE__ .loader {
  height: 5px;
  width: 1px;
  position: absolute;
  animation: rotate0234 3.5s linear infinite;
}

.__UIV_SCOPE__ .loader .dot {
  top: 30px;
  height: 7px;
  width: 7px;
  background: #268fe4;
  border-radius: 50%;
  position: relative;
}

.__UIV_SCOPE__ .text {
  position: absolute;
  bottom: -85px;
  font-size: 25px;
  font-weight: 400;
  color: #26aee4;
}

@keyframes rotate0234 {
  30% {
    transform: rotate(220deg);
  }

  40% {
    transform: rotate(450deg);
    opacity: 1;
  }

  75% {
    transform: rotate(720deg);
    opacity: 1;
  }

  76% {
    opacity: 0;
  }

  100% {
    opacity: 0;
    transform: rotate(0deg);
  }
}

.__UIV_SCOPE__ .loader:nth-child(1) {
  animation-delay: 0.15s;
}

.__UIV_SCOPE__ .loader:nth-child(2) {
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader:nth-child(3) {
  animation-delay: 0.45s;
}

.__UIV_SCOPE__ .loader:nth-child(4) {
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader:nth-child(5) {
  animation-delay: 0.75s;
}

.__UIV_SCOPE__ .loader:nth-child(6) {
  animation-delay: 0.9s;
}
